        var id=bits.Ue();var space=bits.Ue();var chroma=bits.Ue();if(space!=0||chroma!=0)throw new NotSupportedException("Unsupported FEL mapping color domain.");var pivots=new double[3][];for(var c=0;c<3;c++){var pieces=bits.Ue()+1;if(pieces>8)throw new InvalidDataException("Too many FEL curve pieces.");pivots[c]=new double[pieces+1];var sum=0;for(var i=0;i<=pieces;i++){sum+=bits.Read(10);if(sum>1023||i>0&&sum<=pivots[c][i-1]*1023)throw new InvalidDataException("Invalid FEL pivots.");pivots[c][i]=sum/1023d;}}
        if((!singleLayer&&(bits.Read(3)!=0||bits.Read(10)!=0||bits.Read(10)!=1023))||bits.Ue()!=0||bits.Ue()!=0)throw new NotSupportedException("FEL requires unpartitioned linear-deadzone prediction.");var curves=new DolbyFelCurve[3];for(var c=0;c<3;c++){var pieces=new DolbyFelPiece[pivots[c].Length-1];for(var i=0;i<pieces.Length;i++){var method=bits.Ue();int order;if(method==0){order=bits.Ue()+1;if(order is <1 or >2||order==1&&bits.Read(1)!=0)throw new NotSupportedException("Unsupported FEL polynomial.");}else if(method==1){order=bits.Read(2)+1;if(order>3)throw new InvalidDataException("Invalid FEL MMR order.");}else throw new InvalidDataException("Invalid FEL mapping type.");var coefficients=new double[method==0?order+1:1+order*7];for(var n=0;n<coefficients.Length;n++)coefficients[n]=Signed();pieces[i]=new(method,order,coefficients);}curves[c]=new(pivots[c],pieces);}
        var nlq=new DolbyNlq[3];for(var c=0;c<3;c++){var offset=singleLayer?0:bits.Read(10);var max=singleLayer?1:Unsigned();var slope=singleLayer?0:Unsigned();var threshold=singleLayer?0:Unsigned();if(max<=0||!double.IsFinite(max+slope+threshold))throw new InvalidDataException("Invalid FEL NLQ coefficients.");nlq[c]=new(offset,max,slope,threshold);}var dm=bits.Position;bits.Ue();bits.Ue();bits.Ue();
