        var domain=DolbySignalDomain.Create(nonlinear,offsets,linear,eotf,param0,param1,param2,signalDepth,color,signalChroma,range);

        var prefix=bits.Position;var v1=Blocks();var v2=bits.Data.Count-bits.Position>7?Blocks():[];while(bits.Position<bits.Data.Count)if(bits.Read(1)!=0)throw new InvalidDataException("Invalid FEL RPU trailing data.");
        var output=new HdrBits();output.Data.AddRange(bits.Data.Take(headerEnd));output.Data[flags]=false;output.Data[flags+1]=true;output.Ue(id);output.Ue(0);output.Ue(0);for(var c=0;c<3;c++){output.Ue(0);output.Put(0,10);output.Put(1023,10);}output.Ue(0);output.Ue(0);for(var c=0;c<3;c++){output.Ue(0);output.Ue(0);output.Put(0,1);output.Ue(0);output.Put(0,denominator);output.Ue(1);output.Put(0,denominator);}output.Data.AddRange(bits.Data.GetRange(dm,signalStart-dm));if(domain is null)output.Data.AddRange(bits.Data.GetRange(signalStart,prefix-signalStart));else{foreach(var v in DolbySignalDomain.CanonicalNonlinear)output.Put(v&65535,16);foreach(var v in DolbySignalDomain.CanonicalOffset){output.Put((int)(v>>16),16);output.Put((int)(v&65535),16);}foreach(var v in DolbySignalDomain.CanonicalLinear)output.Put(v&65535,16);output.Put(65535,16);output.Put(0,16);output.Put(0,16);output.Put(0,16);output.Put(0,16);output.Put(12,5);output.Put(0,2);output.Put(0,2);output.Put(1,2);output.Data.AddRange(bits.Data.GetRange(prefix-34,34));}Write(v1);if(v2.Count>0)Write(v2);output.Align();var bytes=output.Bytes();var tail=new byte[5];BinaryPrimitives.WriteUInt32BigEndian(tail,DolbySpatialRpu.Crc(bytes));tail[4]=0x80;var converted=new byte[]{0x7c,1,25}.Concat(HdrBits.Escape(bytes.Concat(tail))).ToArray();DolbySpatialRpu.Area(converted);return new(converted,curves,nlq,domain);
