        void Write(List<(int Level,byte[] Data)> blocks){output.Ue(blocks.Count);output.Align();foreach(var block in blocks){output.Ue(block.Data.Length);output.Put(block.Level,8);foreach(var b in block.Data)output.Put(b,8);}}
    }
    internal double Compose(int channel,double y,double u,double v,double enhancementCode)
    {
        var curve=Curves[channel];var sample=channel==0?y:channel==1?u:v;var at=0;while(at+1<curve.Pieces.Length&&sample>=curve.Pivots[at+1])at++;var piece=curve.Pieces[at];var coeff=piece.Coefficients;double mapped;
        if(piece.Method==0){mapped=coeff[^1];for(var i=coeff.Length-2;i>=0;i--)mapped=mapped*sample+coeff[i];}
        else{mapped=coeff[0];var terms=new[]{y,u,v,y*u,y*v,u*v,y*u*v};for(var order=1;order<=piece.Order;order++)for(var term=0;term<7;term++)mapped+=coeff[1+(order-1)*7+term]*Math.Pow(terms[term],order);}
        mapped=Math.Clamp(mapped,curve.Pivots[0],curve.Pivots[^1]);var nlq=Nlq[channel];var rr=enhancementCode-nlq.Offset;var residual=rr==0?0:Math.Sign(rr)*((Math.Abs(rr)-0.5)*nlq.Slope+nlq.Threshold);return Math.Clamp(mapped+residual,0,1);
    }
    internal void Reconstruct(ReadOnlySpan<byte> base444,ReadOnlySpan<byte> enhancement444,Span<byte> output12,int width,int height,int elWidth,int elHeight,CancellationToken ct)
    {
        var pixels=checked(width*height);var elPixels=checked(elWidth*elHeight);if(base444.Length!=pixels*6||enhancement444.Length!=elPixels*6||output12.Length!=pixels*6||!(elWidth==width&&elHeight==height||elWidth*2==width&&elHeight*2==height))throw new NotSupportedException("FEL requires matched full- or half-resolution enhancement pictures.");
        Span<double> values=stackalloc double[3];for(var y=0;y<height;y++)for(var x=0;x<width;x++)
        {
            if(x==0&&(y&15)==0)ct.ThrowIfCancellationRequested();var p=y*width+x;var a=BinaryPrimitives.ReadUInt16LittleEndian(base444.Slice(p*2))/1023d;var b=BinaryPrimitives.ReadUInt16LittleEndian(base444.Slice((pixels+p)*2))/1023d;var c=BinaryPrimitives.ReadUInt16LittleEndian(base444.Slice((pixels*2+p)*2))/1023d;
            for(var channel=0;channel<3;channel++){var fx=Math.Clamp((x+0.5)*elWidth/width-0.5,0,elWidth-1);var fy=Math.Clamp((y+0.5)*elHeight/height-0.5,0,elHeight-1);var ix=(int)fx;var iy=(int)fy;var jx=Math.Min(ix+1,elWidth-1);var jy=Math.Min(iy+1,elHeight-1);var dx=fx-ix;var dy=fy-iy;var start=channel*elPixels;var n00=BinaryPrimitives.ReadUInt16LittleEndian(enhancement444.Slice((start+iy*elWidth+ix)*2));var n01=BinaryPrimitives.ReadUInt16LittleEndian(enhancement444.Slice((start+iy*elWidth+jx)*2));var n10=BinaryPrimitives.ReadUInt16LittleEndian(enhancement444.Slice((start+jy*elWidth+ix)*2));var n11=BinaryPrimitives.ReadUInt16LittleEndian(enhancement444.Slice((start+jy*elWidth+jx)*2));if((n00|n01|n10|n11)>1023||a>1||b>1||c>1)throw new InvalidDataException("Invalid FEL sample precision.");var el=(n00*(1-dx)+n01*dx)*(1-dy)+(n10*(1-dx)+n11*dx)*dy;values[channel]=Compose(channel,a,b,c,el);}
            Signal?.Convert(values);for(var channel=0;channel<3;channel++){BinaryPrimitives.WriteUInt16LittleEndian(output12.Slice((channel*pixels+p)*2),(ushort)Math.Round(values[channel]*4095,MidpointRounding.AwayFromZero));}
        }
    }
}
